'use client';
import Link from 'next/link';
import { User, Activity, Search } from 'lucide-react';

export default function Navbar() {
  return (
    <nav className="glass" style={{ 
      position: 'fixed', 
      top: 0, 
      left: 0, 
      right: 0, 
      zIndex: 1000, 
      height: 'var(--header-height)',
      borderBottom: '1px solid rgba(255,255,255,0.05)'
    }}>
      <div className="container" style={{ 
        height: '100%', 
        display: 'flex', 
        alignItems: 'center', 
        justifyContent: 'space-between' 
      }}>
        <Link href="/" style={{ 
          fontSize: '1.8rem', 
          fontWeight: 'bold', 
          display: 'flex', 
          alignItems: 'center', 
          gap: '10px' 
        }}>
           <div style={{ background: 'var(--primary)', padding: '6px', borderRadius: '8px', display: 'flex' }}>
             <Activity size={24} color="#fff" />
           </div>
           <span className="text-gradient">Suvidha</span>
        </Link>
        
        <div className="desktop-menu" style={{ display: 'flex', gap: '2rem', alignItems: 'center' }}>
             <Link href="/lab-tests" className="nav-item">Lab Tests</Link>
             <Link href="/hospitals" className="nav-item">Hospital Services</Link>
             <Link href="/doctors" className="nav-item">Find Doctors</Link>
             <Link href="/offers" className="nav-item" style={{ color: 'var(--accent)' }}>Offers</Link>
        </div>

        <div style={{ display: 'flex', gap: '1.5rem', alignItems: 'center' }}>
            <div style={{ position: 'relative' }}>
                <Search size={22} style={{ color: 'var(--text-muted)' }} />
            </div>
             <Link href="/profile" className="btn btn-primary" style={{ padding: '0.5rem 1rem', fontSize: '0.9rem' }}>
                Login
            </Link>
        </div>
      </div>

      <style jsx>{`
        .nav-item {
           color: var(--text-muted);
           font-weight: 500;
           transition: all 0.2s;
           font-size: 0.95rem;
        }
        .nav-item:hover {
           color: var(--primary);
        }
        @media (max-width: 768px) {
           .desktop-menu { display: none !important; }
        }
      `}</style>
    </nav>
  );
}
